/* Select trigger — looks like an input but opens a dropdown.
 * Built on top of <Dropdown>, so positioning/keyboard/ARIA already handled. */
.select-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  min-width: 10rem;   /* select-only knob */
  /* ...but never wider than what is holding it. The trigger sizes itself to the longest option it
   * can display, and inside a card that is 20rem wide an option of sixty characters simply left
   * the card — measured on a team whose week status is "5-Already testing / using it with real
   * users or in a real workflow". A control that grows past its parent is the parent's problem
   * everywhere it is used, so it is fixed once, here. */
  max-inline-size: 100%;
  height: var(--control-height);
  padding: 0 var(--control-padding-x);   /* match btn/input */
  background: var(--background);
  color: var(--foreground);
  border: 1px solid var(--input);
  border-radius: var(--control-radius);
  font-family: inherit;
  font-size: var(--control-font-size);
  font-weight: var(--font-weight-regular);   /* value text reads like an input, not a button */
  cursor: pointer;
  white-space: nowrap;
  transition: border-color var(--duration-fast);
}
/* Sizes — mirror the button/control scale. */
.select-trigger[data-size="sm"] { height: var(--control-height-sm); padding-inline: var(--space-3); font-size: var(--font-sm); }
.select-trigger[data-size="lg"] { height: var(--control-height-lg); font-size: var(--control-font-size-lg); }

.select-trigger:hover { border-color: var(--ring); }
.select-trigger:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}
/* Pressed: one stop past hover, the third answer every control now gives. */
.select-trigger:active:not(:disabled) { border-color: var(--primary-active); }
.select-trigger[data-open] { border-color: var(--ring); }
.select-trigger[data-placeholder] { color: var(--muted-foreground); }
.select-trigger[data-invalid] { border-color: var(--destructive); }
/* --muted surface: the white trigger separates itself, so drop the border
 * (invalid + focus outline still show). */
.select-trigger[data-surface="muted"]:not([data-invalid]),
.select-trigger[data-surface="muted"]:not([data-invalid]):hover,
.select-trigger[data-surface="muted"]:not([data-invalid])[data-open] { border-color: transparent; }
.select-trigger[data-invalid]:focus-visible { outline-color: var(--destructive); }
.select-trigger:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}
.select-trigger .icon { color: var(--icon-muted); }

/* Selection (trailing primary check) is handled centrally by DropdownItem. */

/* The chosen value, which is the part that can be any length. It shortens with an ellipsis rather
 * than pushing the trigger wider: the whole value is one click away in the menu, and the trigger's
 * aria-label carries it for anyone not looking at the pixels. */
.select-value {
  overflow: hidden;
  min-inline-size: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

import './Select.css'
import { cn } from '../lib/cn'
import { type Option } from '../lib/option'
import { Icon } from '../Icon'
import { Dropdown, DropdownItem } from '../Dropdown'

/** A Select choice: the shared <Option> plus the one thing this control also
 *  renders — a choice shown but not pickable (an out-of-stock plan). */
export type SelectOption<V extends string> = Option<V> & { disabled?: boolean }

type Props<V extends string> = {
  value: V | undefined
  onChange: (next: V) => void
  options: readonly SelectOption<V>[]
  placeholder?: string
  /** Accessible label — applied to the trigger button. */
  label: string
  /** Lands on the trigger, so `<Field htmlFor>` reaches it and an `ErrorSummary`
   *  row can put focus on it. Without one the field is unreachable by name: a
   *  failed submit listed "Choose who takes this request", the row linked to an
   *  id nothing carried, and clicking it did nothing at all (owner, 2026-08-23). */
  id?: string
  className?: string
  /** sm / md (default) / lg — matches the control scale. */
  size?: 'sm' | 'md' | 'lg'
  /** Not editable and not openable. */
  disabled?: boolean
  /**
   * Failed validation: paints the red border. It does NOT announce anything, and
   * the description here used to claim `aria-invalid`, which the component never
   * set — and could not: the trigger is a `<button>`, and `aria-invalid` is not
   * supported on that role. Nor is the widget a real ARIA combobox: its popup is
   * a `menu` of `menuitem`s, so calling the trigger a combobox would be a
   * different lie. Until a listbox-based select exists, the error TEXT is what
   * carries the meaning, and the caller has to associate it — `<Field>` has no
   * error slot yet, which is the actual gap.
   */
  invalid?: boolean
  /** Which surface the field sits on. On `muted` (a page/PageHeader) the border
   *  is dropped since the white fill separates it; `base` (default, a white card
   *  or form) keeps the border. Invalid + focus stay visible on both. */
  surface?: 'base' | 'muted'
}

/**
 * Single choice from a short list, built on Dropdown so the menu can match the
 * trigger width. Combobox is the one for a long list.
 *
 * Copy: the label names the value, the placeholder names the choice not yet made
 * — "Choose a region". Options are parallel and never restate the label.
 */
export function Select<V extends string>({
  value, onChange, options, placeholder, label, id, className, size, disabled, invalid, surface = 'base',
}: Props<V>) {
  const selected = options.find((o) => o.value === value)
  const display = selected?.label ?? placeholder ?? ''

  return (
    <Dropdown
      align="start"
      /* The menu is exactly as wide as the field. Both this component's own doc
         comment and the system contract said so; neither was true, because
         nothing passed the option through and the `select-menu` class it did
         pass was styled by nobody. A choice list narrower or wider than the
         field it belongs to reads as a different control. */
      matchTriggerWidth
      /* Through the Dropdown, not onto the button: the menu labels itself by the
         trigger's id, so the two have to be the same one. */
      triggerId={id}
      trigger={({ isOpen, ...triggerProps }) => (
        <button
          type="button"
          className={cn('select-trigger', className)}
          data-size={size}
          data-open={isOpen || undefined}
          data-placeholder={!selected || undefined}
          data-invalid={invalid || undefined}
          data-surface={surface}
          disabled={disabled || undefined}
          aria-label={label}
          {...triggerProps}
        >
          <span className="select-value">{display}</span>
          <Icon name="arrow_drop_down" />
        </button>
      )}
    >
      {options.map((opt) => (
        <DropdownItem
          key={opt.value}
          onClick={() => onChange(opt.value)}
          selected={opt.value === value}
          disabled={opt.disabled}
        >
          {opt.label}
        </DropdownItem>
      ))}
    </Dropdown>
  )
}
